const { EventEmitter } = require("node:events");
const bus = new EventEmitter();

bus.on("commande:cree", (commande) => {
  console.log(`Commande ${commande.id}`);
});

bus.emit("commande:cree", { id: 42 });

const { EventEmitter } = require("node:events");
const bus = new EventEmitter();
bus.once("pret", valeur => console.log(valeur));
bus.emit("pret", "une fois");
bus.emit("pret", "deux fois");
